/* Native C11 OpenXzuff LAP/LUAP installer foundation. ZIP_STORED only. */
#include <ctype.h>
#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#define MAX_ARCHIVE (64u*1024u*1024u)
#define MAX_FILES 2048u
#define MAX_ENTRY (32u*1024u*1024u)
#define MAX_TOTAL (128u*1024u*1024u)
#define PATH_CAP 1024u
typedef struct { char *name; uint32_t crc,cs,us,off; uint16_t method,flags; } ent;
static uint16_t r16(const uint8_t*p){return (uint16_t)(p[0]|((uint16_t)p[1]<<8));}
static uint32_t r32(const uint8_t*p){return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
static uint32_t crc32b(const uint8_t*p,size_t n){uint32_t c=~0u;size_t i;int k;for(i=0;i<n;i++){c^=p[i];for(k=0;k<8;k++)c=(c>>1)^(0xedb88320u&(uint32_t)-(int32_t)(c&1u));}return ~c;}
static int safe(const char*s){const char*p=s,*q=s;if(!s||!*s||*s=='/'||strchr(s,'\\')||strchr(s,':'))return 0;for(;*p;p++)if(*p=='/'){size_t n=(size_t)(p-q);if(!n||(n==1&&q[0]=='.')||(n==2&&q[0]=='.'&&q[1]=='.'))return 0;q=p+1;}if(q==p||(p-q==1&&q[0]=='.')||(p-q==2&&q[0]=='.'&&q[1]=='.'))return 0;return 1;}
static int field(const char*j,const char*k,char*out,size_t cap){char key[80];const char*p,*q;if(snprintf(key,sizeof key,"\"%s\"",k)>=(int)sizeof key)return -1;p=strstr(j,key);if(!p||strstr(p+strlen(key),key))return -1;p+=strlen(key);while(isspace((unsigned char)*p))p++;if(*p++!=':')return -1;while(isspace((unsigned char)*p))p++;if(*p++!='"')return -1;q=p;while(*q&&*q!='"'){if(*q=='\\'||(unsigned char)*q<32)return -1;q++;}if(*q!='"'||(size_t)(q-p)+1>cap)return -1;memcpy(out,p,(size_t)(q-p));out[q-p]=0;return 0;}
static int manifest(const uint8_t*b,size_t n,const char*ext){char*j,*f,*l,*e,*id,*v;int ok=0;size_t i;if(!n||n>65536||memchr(b,0,n))return 0;j=malloc(n+1);f=calloc(16,1);l=calloc(16,1);e=calloc(PATH_CAP,1);id=calloc(256,1);v=calloc(64,1);if(!j||!f||!l||!e||!id||!v)goto done;memcpy(j,b,n);j[n]=0;for(i=0;i<n;i++)if((unsigned char)j[i]<9||((unsigned char)j[i]>13&&(unsigned char)j[i]<32))goto done;if(field(j,"format",f,16)||field(j,"language",l,16)||field(j,"entry",e,PATH_CAP)||field(j,"id",id,256)||field(j,"version",v,64))goto done;if(strcmp(f,!strcmp(ext,".lap")?"LAP":"LUAP")||strcmp(l,!strcmp(ext,".lap")?"Luau":"Lua")||!safe(e)||!strchr(id,'.')||strchr(id,'/')||strchr(id,' '))goto done;if(!strcmp(ext,".lap")){size_t z=strlen(e);if(z<5||strcmp(e+z-5,".luau"))goto done;}else{size_t z=strlen(e);if(z<4||strcmp(e+z-4,".lua"))goto done;}if(!isdigit((unsigned char)v[0])||!strchr(v,'.'))goto done;ok=1;done:free(j);free(f);free(l);free(e);free(id);free(v);return ok;}
static int load(const char*p,uint8_t**b,size_t*n){FILE*f=fopen(p,"rb");long z;if(!f)return -1;if(fseek(f,0,SEEK_END)||(z=ftell(f))<0||(unsigned long)z>MAX_ARCHIVE||fseek(f,0,SEEK_SET)){fclose(f);return -1;}*b=malloc(z?(size_t)z:1);if(!*b){fclose(f);return -1;}*n=(size_t)z;if(fread(*b,1,*n,f)!=*n){free(*b);fclose(f);return -1;}fclose(f);return 0;}
static int mkparents(const char*root,const char*rel){char p[PATH_CAP];size_t i,n;if(snprintf(p,sizeof p,"%s/%s",root,rel)>=(int)sizeof p)return -1;n=strlen(p);for(i=strlen(root)+1;i<n;i++)if(p[i]=='/'){p[i]=0;if(mkdir(p,0700)&&errno!=EEXIST)return -1;p[i]='/';}return 0;}
static int install(const char*pkg,const char*root){uint8_t*b=NULL;size_t n=0,i,c,total=0;uint32_t cd,cds;uint16_t num;ent*es=NULL;size_t mi=(size_t)-1;char ext[8],dest[PATH_CAP],stage[PATH_CAP];int rc=2;if(strlen(pkg)<5)goto bad;strcpy(ext,pkg+strlen(pkg)-5);if(strcmp(ext,".lap")&&strcmp(ext,".luap"))goto bad;if(load(pkg,&b,&n)||n<22){fprintf(stderr,"ERROR: unreadable ZIP\n");goto end;}for(i=n-22+1;i-->(n>65557?n-65557:0);)if(r32(b+i)==0x06054b50u)break;if(r32(b+i)!=0x06054b50u){fprintf(stderr,"ERROR: ZIP end record missing\n");goto end;}if(r16(b+i+4)||r16(b+i+6)||r16(b+i+8)!=r16(b+i+10)){fprintf(stderr,"ERROR: multi-disk ZIP unsupported\n");goto end;}num=r16(b+i+10);cds=r32(b+i+12);cd=r32(b+i+16);if(!num||num>MAX_FILES||(uint64_t)cd+cds>n){fprintf(stderr,"ERROR: invalid central directory\n");goto end;}es=calloc(num,sizeof(*es));if(!es)goto end;i=cd;for(c=0;c<num;c++){uint16_t nl,xl,cl;size_t j;if(i+46>n||r32(b+i)!=0x02014b50u)goto badzip;es[c].flags=r16(b+i+8);es[c].method=r16(b+i+10);es[c].crc=r32(b+i+16);es[c].cs=r32(b+i+20);es[c].us=r32(b+i+24);nl=r16(b+i+28);xl=r16(b+i+30);cl=r16(b+i+32);es[c].off=r32(b+i+42);if(!nl||nl>=PATH_CAP||i+46u+nl+xl+cl>n)goto badzip;es[c].name=malloc(nl+1);if(!es[c].name)goto end;memcpy(es[c].name,b+i+46,nl);es[c].name[nl]=0;if(es[c].name[nl-1]=='/')es[c].name[nl-1]=0;if(!safe(es[c].name))goto badpath;for(j=0;j<c;j++)if(!strcmp(es[j].name,es[c].name))goto badzip;if(es[c].flags&1u||es[c].method!=0||es[c].cs!=es[c].us||es[c].us>MAX_ENTRY||total>MAX_TOTAL-es[c].us)goto badzip;total+=es[c].us;if(!strcmp(es[c].name,"manifest.json"))mi=c;i+=46u+nl+xl+cl;}if(mi==(size_t)-1)goto badzip;{ent*e=&es[mi];size_t o=e->off;if(o+30>n||r32(b+o)!=0x04034b50u)goto badzip;o+=30u+r16(b+o+26)+r16(b+o+28);if(o+e->us>n||crc32b(b+o,e->us)!=e->crc||!manifest(b+o,e->us,ext)){fprintf(stderr,"ERROR: manifest validation failed\n");goto end;}}
if(mkdir(root,0700)&&errno!=EEXIST){perror("mkdir root");goto end;} {ent*e=&es[mi];size_t o=e->off;char*js,*id=calloc(256,1);o+=30u+r16(b+o+26)+r16(b+o+28);js=malloc(e->us+1);if(!js||!id)goto end;memcpy(js,b+o,e->us);js[e->us]=0;if(field(js,"id",id,256)){free(js);free(id);goto end;}free(js);if(snprintf(dest,sizeof dest,"%s/%s",root,id)>=(int)sizeof dest||snprintf(stage,sizeof stage,"%s/.staging-%ld",root,(long)getpid())>=(int)sizeof stage){free(id);goto end;}free(id);if(access(dest,F_OK)==0){fprintf(stderr,"ERROR: app already installed; refusing overwrite\n");goto end;}if(mkdir(stage,0700)){perror("mkdir staging");goto end;}}
for(c=0;c<num;c++){ent*e=&es[c];size_t o=e->off;char p[PATH_CAP];FILE*f;if(o+30>n||r32(b+o)!=0x04034b50u)goto stagefail;o+=30u+r16(b+o+26)+r16(b+o+28);if(o+e->us>n||crc32b(b+o,e->us)!=e->crc)goto stagefail;if(snprintf(p,sizeof p,"%s/%s",stage,e->name)>=(int)sizeof p||mkparents(stage,e->name))goto stagefail;f=fopen(p,"wb");if(!f)goto stagefail;if(fwrite(b+o,1,e->us,f)!=e->us||fclose(f)){goto stagefail;}}
if(rename(stage,dest)){perror("activate install");goto stagefail;}printf("INSTALLED: %s\nPATH: %s\nScripts were not executed.\n",dest,dest);rc=0;goto end;
stagefail:fprintf(stderr,"ERROR: installation failed; staging directory retained at %s\n",stage);goto end;
badpath:fprintf(stderr,"ERROR: unsafe package path\n");goto end;
badzip:fprintf(stderr,"ERROR: unsupported or malformed ZIP (only ZIP_STORED is supported)\n");goto end;
bad:fprintf(stderr,"Usage: oxz-install install PACKAGE.lap|PACKAGE.luap APP_ROOT\n");
end:if(es){for(i=0;i<(size_t)num;i++)free(es[i].name);free(es);}free(b);return rc;}
int main(int argc,char**argv){if(argc==4&&!strcmp(argv[1],"install"))return install(argv[2],argv[3]);fprintf(stderr,"Usage: %s install PACKAGE.lap|PACKAGE.luap APP_ROOT\n",argv[0]);return 2;}
